import type { HTMLAttributes } from "react";

export function Spinner({ className = "", "aria-label": label = "Loading", ...props }: HTMLAttributes<HTMLSpanElement>) {
  return <span role="status" aria-label={label} className={`co-inline-block co-size-5 co-animate-spin co-rounded-full co-border-2 co-border-black/20 co-border-t-black ${className}`.trim()} {...props} />;
}
